import {W,H,T,visibleObject} from './world.js';
const colors={village:{ground:'#67806a',speck:'#82917a',path:'#a29c7e',tree:'#395f52',wall:'#64777a'},forest:{ground:'#3c6257',speck:'#557c65',path:'#918e6d',tree:'#284f44',wall:'#385751'},mine:{ground:'#4c5153',speck:'#626469',path:'#68645b',tree:'#345b4b',wall:'#303d43'},ruins:{ground:'#3a5356',speck:'#506b69',path:'#4d6867',tree:'#345b4b',wall:'#253f45'},heart:{ground:'#293f48',speck:'#40565c',path:'#49676b',tree:'#345b4b',wall:'#263d46'}};
function hash(x,y,s=1){let n=Math.sin(x*127.1+y*311.7+s*74.7)*43758.5453;return n-Math.floor(n);}
export class Renderer{constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.buf=document.createElement('canvas');this.buf.width=480;this.buf.height=320;this.c=this.buf.getContext('2d');this.cam={x:0,y:0};this.time=0;this.particles=[];this.flash=0;}
rect(x,y,w,h,color){this.c.fillStyle=color;this.c.fillRect(Math.round(x),Math.round(y),w,h)}
ellipse(x,y,rx,ry,color){this.c.fillStyle=color;this.c.beginPath();this.c.ellipse(x,y,rx,ry,0,0,Math.PI*2);this.c.fill()}
poly(points,color){this.c.fillStyle=color;this.c.beginPath();points.forEach(([x,y],i)=>i?this.c.lineTo(x,y):this.c.moveTo(x,y));this.c.closePath();this.c.fill()}
text(str,x,y,color='#dfd9b7',size=7){this.c.font=`${size}px sans-serif`;this.c.textAlign='center';this.c.fillStyle='#0c2428';this.c.fillText(str,x+1,y+1);this.c.fillStyle=color;this.c.fillText(str,x,y);}
sprite(type,x,y,time=0,dir='down',scale=1){const c=this.c;c.save();c.translate(Math.round(x),Math.round(y));c.scale(scale,scale);let step=Math.sin(time*12)>0?1:0;this.ellipse(0,3,7,3,'#0a242c65');if(type==='noa'){this.poly([[-8,0],[-13,-4],[-12,0],[-7,3]],'#a0c9c2');this.rect(-7,-5,10,7,'#b3cdc0');this.rect(2,-8,6,6,'#d3dbbf');this.rect(-6,1,2,4,'#6c9695');this.rect(0,1,2,4,'#6c9695');this.rect(3,-6,2,2,'#315661');this.rect(1,-1,2,3,'#b7fff0');c.restore();return;}
const hair=type==='yuris'?'#825a3e':type==='ed'?'#493b32':type==='elder'?'#d2cdb3':type==='woman'?'#8b573b':'#69554a';const coat=type==='yuris'?'#b99258':type==='ed'?'#465e84':type==='elder'?'#8a7264':type==='woman'?'#8a807a':type==='smith'?'#836245':'#748382';this.rect(-4,-2,3,6+step,'#343f45');this.rect(1,-2,3,7-step,'#343f45');this.rect(-5,5+step,4,2,'#26383d');this.rect(1,6-step,4,2,'#26383d');this.rect(-5,-11,10,11,coat);this.rect(-3,-10,2,10,type==='yuris'?'#d0b17b':'#a2aaa2');this.rect(-7,-9,2,9,'#c7a281');this.rect(5,-9,2,9,'#c7a281');this.rect(-4,-19,9,9,'#d9b697');this.rect(-5,-20,11,4,hair);this.rect(-5,-17,2,6,hair);this.rect(4,-17,2,5,hair);if(type==='yuris'){this.rect(5,-17,3,9,hair);this.rect(5,-13,3,2,'#b7c8b1');}if(dir!=='up'){this.rect(-2,-15,1,2,'#354955');this.rect(2,-15,1,2,'#354955');}else this.rect(-4,-18,9,7,hair);if(type==='knight'){this.rect(-6,-12,3,9,'#c3c6ad');this.rect(7,-13,2,13,'#d2d5c5');}c.restore();}
tree(x,y,tint){this.ellipse(x+8,y+9,14,6,'#183c3b55');this.rect(x+5,y-7,6,19,'#655e4b');this.poly([[x-9,y],[x+8,y-30],[x+25,y]],tint);this.poly([[x-6,y-10],[x+8,y-37],[x+22,y-10]],'#426955');this.poly([[x-2,y-21],[x+8,y-43],[x+18,y-21]],'#52785e');this.poly([[x+2,y-29],[x+8,y-43],[x+13,y-29]],'#bec7b1');this.rect(x-8,y,12,2,'#294c42');}
crystal(x,y,size=1,color='#99ead7'){const c=this.c;c.save();c.translate(x,y);c.scale(size,size);const glow=c.createRadialGradient(0,-9,0,0,-9,32);glow.addColorStop(0,'#72d9ce55');glow.addColorStop(1,'#72d9ce00');c.fillStyle=glow;c.fillRect(-32,-42,64,64);this.poly([[0,-24],[9,-12],[7,2],[0,8],[-8,1],[-9,-13]],color);this.poly([[0,-24],[0,8],[-8,1],[-9,-13]],'#629e9f');this.poly([[0,-24],[9,-12],[0,-8]],'#d5fff0');this.rect(1,-9,2,11,'#c1f4de');c.restore();}
object(o,x,y,s,m){const c=this.c;const p=colors[m.theme];switch(o.type){case 'tree':this.tree(x+8,y+20,p.tree);break;case 'house':{let w=o.w*16,h=o.h*16;this.ellipse(x+w/2,y+h,w*.55,7,'#15363050');this.rect(x+1,y+12,w-2,h-12,'#c1b796');this.rect(x+3,y+19,w-6,h-21,'#b4ab8f');for(let i=10;i<w;i+=22){this.rect(x+i,y+29,12,12,'#526c69');this.rect(x+i+1,y+30,10,9,'#b2ba91');this.rect(x+i+5,y+29,1,12,'#827c63');}this.rect(x+w/2-6,y+h-18,13,18,'#5b5546');this.rect(x+w/2+3,y+h-9,1,2,'#e0c786');const roof=o.roof==='red'?'#8e6555':o.roof==='green'?'#536d65':'#5e727a';this.poly([[x-5,y+18],[x+w/2,y-9],[x+w+5,y+18]],roof);this.poly([[x-5,y+18],[x+w/2,y-9],[x+w/2,y-3],[x+6,y+18]],'#d3d4bf');for(let j=1;j<4;j++)this.rect(x+8+j*4,y+3+j*4,w-16-j*8,1,'#ced0ac25');this.rect(x+w-19,y-8,7,16,'#8b8c7c');this.text(o.label,x+w/2,y+h+9,'#e1dbb6',6);break;}case 'npc':this.sprite(o.sprite,x+8,y+12,0);if(o.marker){this.ellipse(x+8,y-17,5,6,'#e5c98d');this.text(o.marker,x+8,y-14,'#354848',8);}break;case 'well':this.ellipse(x+8,y+9,11,6,'#9aa69a');this.ellipse(x+8,y+7,8,4,'#36575d');this.rect(x-2,y-10,2,18,'#a8956c');this.rect(x+16,y-10,2,18,'#a8956c');this.poly([[x-5,y-8],[x+8,y-16],[x+21,y-8]],'#6d7770');break;case 'exit':{let blocked=o.lock&&!s.flags[o.lock];const pulse=.6+Math.sin(this.time*2)*.2;this.ellipse(x+8,y+9,13,6,blocked?'#bfa37866':`rgba(149,211,193,${pulse})`);this.text(blocked?'◇':'↑',x+8,y+11,'#fcf1bd',12);if(o.to==='village')this.text('←',x+8,y+11,'#fcf1bd',12);break;}case 'ore':this.crystal(x+8,y+10,.5);break;case 'herb':this.rect(x+7,y+3,2,9,'#b8c783');this.poly([[x+7,y+7],[x,y+1],[x+2,y+10]],'#91bc78');this.poly([[x+8,y+5],[x+15,y-1],[x+13,y+7]],'#c1d397');this.ellipse(x+8,y-1,3,2,'#e4cdb2');break;case 'chest':this.rect(x+1,y+1,15,12,'#6b5341');this.rect(x+1,y,15,5,'#a88853');this.rect(x+3,y,2,13,'#d0b77c');this.rect(x+12,y,2,13,'#d0b77c');this.rect(x+7,y+5,3,4,'#f0d8a0');break;case 'spring':{const glow=c.createRadialGradient(x+8,y+4,0,x+8,y+4,25);glow.addColorStop(0,'#b2e5ce77');glow.addColorStop(1,'#79bfbe00');c.fillStyle=glow;c.fillRect(x-17,y-21,50,50);this.ellipse(x+8,y+7,12,6,'#869990');this.ellipse(x+8,y+5,9,4,'#75b9b5');this.rect(x+5,y-6,6,8,'#aedfd1');this.rect(x+7,y-10,2,12,'#e1eec6');break;}case 'sign':this.rect(x+7,y+3,2,13,'#74664e');this.rect(x,y-3,17,10,'#b8a374');this.rect(x+3,y,10,1,'#786a50');this.rect(x+3,y+3,7,1,'#786a50');break;case 'tablet':this.rect(x+1,y-7,15,22,'#7c918b');this.rect(x+3,y-5,11,18,'#405c60');for(let j=0;j<4;j++)this.rect(x+5,y-2+j*4,7-(j%2)*2,1,'#9dc6b4');this.ellipse(x+8,y-12,2,2,s.lore.includes(o.lore)?'#8db8a3':'#e3c784');break;case 'pump':this.rect(x,y-5,24,20,'#576f70');this.ellipse(x+12,y,9,9,'#9da394');this.ellipse(x+12,y,5,5,s.flags.pump?'#a4dec5':'#6b6561');this.rect(x+20,y+5,14,4,'#a3a993');this.rect(x+31,y+5,3,12,'#a3a993');break;case 'valve':this.rect(x+3,y-2,10,17,'#7b8982');this.ellipse(x+8,y-5,10,10,s.valves.includes(o.id)?'#c8d8ad':'#47676c');this.ellipse(x+8,y-5,7,7,o.color);this.text(o.symbol,x+8,y-2,'#243e46',8);this.rect(x+7,y+4,2,14,s.valves.includes(o.id)?'#d5dca7':'#728a7e');break;case 'crystal':this.crystal(x+8,y+14,2.6);break;case 'enemy':this.monster(o.enemy,x+8,y+9,.21);break;case 'boss':this.monster('bear',x+8,y+12,.38);break;}}
monster(kind,x,y,scale=1){let c=this.c;c.save();c.translate(Math.round(x),Math.round(y));c.scale(scale,scale);this.ellipse(0,18,63,15,'#06151b66');const float=Math.sin(this.time*2)*3;c.translate(0,kind==='moth'?float:0);if(kind==='wolf'){this.poly([[-40,1],[-65,-24],[-57,4],[-37,12]],'#a0b9b5');this.rect(-37,-29,61,37,'#a0b9b5');this.rect(-31,-23,49,17,'#bdccba');this.rect(-32,3,12,25,'#718f94');this.rect(7,3,12,25,'#718f94');this.rect(-35,22,18,6,'#c1ccbd');this.rect(4,22,18,6,'#c1ccbd');this.poly([[13,-23],[9,-65],[28,-43],[38,-62],[43,-25]],'#b8c9be');this.rect(17,-42,28,26,'#b8c9be');this.rect(31,-27,25,11,'#cdd7c4');this.rect(23,-36,7,5,'#d8c583');this.rect(46,-27,10,6,'#36565f');this.rect(38,-14,4,5,'#f2ebd0');}
else if(kind==='moth'){this.poly([[-5,-20],[-67,-62],[-58,-5],[-28,23],[0,9]],'#88bdb3');this.poly([[5,-20],[67,-62],[58,-5],[28,23],[0,9]],'#9bcec0');this.poly([[-8,-15],[-54,-44],[-42,-5],[-22,10]],'#547b87');this.poly([[8,-15],[54,-44],[42,-5],[22,10]],'#547b87');this.ellipse(-37,-19,10,12,'#c7dba1');this.ellipse(37,-19,10,12,'#c7dba1');this.rect(-6,-35,12,55,'#d0bb87');this.rect(-12,-44,5,14,'#d6ca94');this.rect(7,-44,5,14,'#d6ca94');this.ellipse(0,-28,9,10,'#d5dec2');this.rect(-4,-30,2,3,'#3a5a60');this.rect(3,-30,2,3,'#3a5a60');}
else if(kind==='crawler'){for(let i=-2;i<=2;i++){this.rect(i*21-8,1,7,20,'#8b9690');this.rect(i*21-11,18,14,5,'#a3b0a3');}this.ellipse(0,-6,57,31,'#5e7c7b');for(let i=-2;i<=2;i++)this.poly([[i*20-13,4],[i*20-12,-28],[i*20,-41],[i*20+12,-23],[i*20+9,9]],i%2?'#a1b7a5':'#7f9c92');this.rect(40,-5,25,19,'#a8beac');this.rect(54,-2,5,4,'#e2d09c');this.poly([[56,10],[73,16],[60,19]],'#d0c8a5');}
else if(kind==='sentinel'){this.rect(-28,-9,18,37,'#6f8987');this.rect(12,-9,18,37,'#6f8987');this.rect(-34,23,28,9,'#afab8d');this.rect(9,23,28,9,'#afab8d');this.poly([[-38,-62],[32,-62],[39,-18],[20,-3],[-25,-3],[-42,-21]],'#899f93');this.rect(-28,-53,46,36,'#536f73');this.crystal(-4,-29,.8,'#a9ead0');this.rect(-28,-89,43,28,'#b0b29b');this.rect(-19,-79,35,6,'#43666d');this.rect(-13,-78,17,3,'#d9e4b7');this.rect(-62,-52,17,50,'#99a996');this.rect(41,-52,18,50,'#99a996');this.rect(49,-8,6,38,'#c6c6a8');this.poly([[45,30],[52,46],[60,30]],'#bdd7c6');this.rect(-65,-7,22,13,'#6b8785');}
else{this.rect(-57,-12,29,42,'#5b7f7e');this.rect(27,-12,29,42,'#5b7f7e');this.rect(-65,20,39,12,'#a2ab91');this.rect(25,20,39,12,'#a2ab91');this.ellipse(0,-30,68,46,'#7f998d');this.poly([[-59,-57],[-24,-77],[30,-72],[61,-44],[48,-12],[-47,-10]],'#9bab92');this.rect(-43,-49,11,36,'#bdba8f');this.rect(31,-49,11,36,'#bdba8f');this.ellipse(-28,-81,14,16,'#889e8c');this.ellipse(28,-81,14,16,'#889e8c');this.rect(-34,-86,68,48,'#b1b89b');this.rect(-28,-79,56,30,'#8aa593');this.rect(-24,-69,16,6,'#244d57');this.rect(8,-69,16,6,'#244d57');this.rect(-21,-68,10,3,'#b3f0d8');this.rect(11,-68,10,3,'#b3f0d8');this.rect(-16,-57,32,16,'#c0c7a9');this.rect(-8,-58,16,7,'#4b7273');this.crystal(0,-17,.75,'#c0f0d0');for(let a of [-47,42])for(let i=0;i<3;i++)this.rect(a+i*5,29,3,5,'#d1ccb0');}
c.restore();}
draw(m,s,battle,dt,title=false){this.time+=dt;let c=this.c;c.clearRect(0,0,480,320);const p=colors[m.theme];c.fillStyle=p.ground;c.fillRect(0,0,480,320);if(battle){this.battleScene(m,s,battle);this.finish();return;}
let targetX=Math.max(0,Math.min(W*16-480,s.x*16+8-240));let targetY=Math.max(0,Math.min(H*16-320,s.y*16+8-160));this.cam.x+=(targetX-this.cam.x)*Math.min(1,dt*10);this.cam.y+=(targetY-this.cam.y)*Math.min(1,dt*10);let cx=Math.round(this.cam.x),cy=Math.round(this.cam.y);c.save();c.translate(-cx,-cy);
for(let y=0;y<H;y++)for(let x=0;x<W;x++){let px=x*16,py=y*16,t=m.tiles[y][x],r=hash(x,y,m.seed);if(px+16<cx||px>cx+480||py+16<cy||py>cy+320)continue;if(t==='#'){this.rect(px,py,16,16,p.wall);this.rect(px,py,16,2,m.theme==='mine'?'#657170':'#738d7b');this.rect(px+1,py+3,14,10,m.theme==='mine'?'#38464a':'#2d4c47');this.rect(px+3,py+8,7,1,'#ffffff0b');if(m.theme==='village'||m.theme==='forest'){this.tree(px+3,py+18,p.tree);}}
else if(t==='w'||t==='v'){this.rect(px,py,16,16,t==='v'?'#18323e':'#477b81');if(t==='w'){let a=Math.floor(this.time*2+x)%4;this.rect(px+2+a,py+5,7,1,'#92beb450');this.rect(px+5-a,py+12,7,1,'#a8d0c345');}else if(r>.8)this.rect(px+7,py+7,1,1,'#9cdcd166');}
else if(t==='p'||t==='b'){this.rect(px,py,16,16,p.path);this.rect(px+Math.floor(r*12),py+7,3,1,'#d0c4a070');if(t==='b'){this.rect(px,py,16,16,'#8d8062');for(let j=0;j<4;j++)this.rect(px,py+j*4,16,1,'#c3b491');}}
else if(t==='r'||t==='q'){this.rect(px,py,16,16,p.ground);this.rect(px,py,16,1,'#6c878033');this.rect(px,py,1,16,'#193c4270');if(r>.65){this.rect(px+4,py+10,6,1,'#8a9d8b33');this.rect(px+9,py+11,1,3,'#172e3455');}if(t==='q'){this.rect(px+6,py,3,16,'#6d9d9377');this.rect(px+7,py,1,16,s.flags.gate?'#c0d8a5':'#91b9aa66');}}
else{this.rect(px,py,16,16,p.ground);if(r>.3){this.rect(px+3,py+6,2,2,p.speck);this.rect(px+11,py+12,3,1,p.speck);}if((m.theme==='village'||m.theme==='forest')&&r>.87){this.rect(px+1,py+3,7,3,'#d7d9bc');this.rect(px+3,py+2,5,2,'#d7d9bc');}if(m.theme==='forest'&&r<.15)this.rect(px+6,py+10,2,2,'#c3bc79');}}
let renderables=m.objects.filter(o=>visibleObject(o,s)).map(o=>({y:o.y+(o.h||1)-1,draw:()=>this.object(o,o.x*16,o.y*16,s,m)}));renderables.push({y:s.y,draw:()=>{this.sprite('ed',s.x*16-8,s.y*16+18,s.steps*.1,s.dir);this.sprite('noa',s.x*16+21,s.y*16+16,this.time);this.sprite('yuris',s.x*16+8,s.y*16+11,s.steps*.1,s.dir);}});renderables.sort((a,b)=>a.y-b.y).forEach(r=>r.draw());c.restore();
for(let i=0;i<30;i++){let x=(hash(i,7)*480+Math.sin(this.time*.25+i)*14)%480,y=(hash(i,9)*340-this.time*(m.theme==='forest'?2:1)+640)%340;this.rect(x,y,1,i%5?1:2,m.theme==='village'||m.theme==='forest'?'#e5e5bf77':'#9ae7d573');}
if(['mine','ruins','heart'].includes(m.theme)){let g=c.createRadialGradient(s.x*16+8-cx,s.y*16+8-cy,45,s.x*16+8-cx,s.y*16+8-cy,270);g.addColorStop(0,'#06162200');g.addColorStop(1,'#031724aa');c.fillStyle=g;c.fillRect(0,0,480,320);}
this.finish();}
battleScene(m,s,b){const c=this.c;const p=colors[m.theme];let g=c.createLinearGradient(0,0,0,320);g.addColorStop(0,'#0e252e');g.addColorStop(.5,p.ground);g.addColorStop(1,'#182f36');c.fillStyle=g;c.fillRect(0,0,480,320);if(m.theme==='forest'){for(let i=0;i<12;i++){c.save();c.translate(i*49-15,145+(i%3)*9);c.scale(2,2);this.tree(0,0,i%2?'#2d5148':'#3b6252');c.restore();}this.ellipse(250,201,160,25,'#6f89643a');}else{for(let i=0;i<8;i++){this.rect(i*70-10,0,25,183,'#273f45');this.rect(i*70-13,0,31,14,'#657a70');this.rect(i*70-13,170,31,13,'#5e786e');for(let j=1;j<6;j++)this.rect(i*70-10,j*30,25,1,'#6b817433');}for(let j=0;j<5;j++){this.rect(0,180+j*25,480,1,'#87a69422');}if(b.boss){this.crystal(245,96,2.4);}}
for(let i=0;i<16;i++)this.rect(hash(i,4)*480,(hash(i,3)*200+this.time*3)%210,1,1,'#c0ddab66');this.monster(b.kind,258,179+Math.sin(this.time*2)*1.5,b.boss?1.15:1);this.sprite('yuris',74,199,0,'up',1.5);this.sprite('ed',113,203,0,'up',1.4);this.sprite('noa',50,205,0,'up',1.2);if(b.boss){this.text(`安定度 ${b.stability} / 7`,257,223,'#c7e9ca',9);}if(this.flash>0){c.fillStyle=`rgba(240,215,155,${this.flash*.25})`;c.fillRect(0,0,480,320);this.flash*=.85;}}
finish(){this.ctx.imageSmoothingEnabled=false;this.ctx.drawImage(this.buf,0,0,960,640);}
portrait(canvas,type){const old=this.c;this.c=canvas.getContext('2d');this.c.clearRect(0,0,46,53);this.c.fillStyle=type==='yuris'?'#475c55':'#3c5261';this.c.fillRect(0,0,46,53);this.sprite(type,23,43,0,'down',1.65);this.c=old;}
}
